contract_clause_fact(contrato_ocs_331_2022, clausula_segunda_vigencia, prazo_manifestacao_prorrogacao, '5 dias úteis', 'Parágrafo Primeiro').
contract_clause_fact(contrato_ocs_331_2022, clausula_segunda_vigencia, prazo_comunicacao_interesse_prorrogacao, '90 dias', 'Parágrafo Segundo').
