contract_clause_fact(contrato_ocs_331_2022, clausula_setima_pagamento, juros_mora, '0,5% {meio por cento) ao  mês', 'Parágrafo Décimo Quarto').
contract_clause_fact(contrato_ocs_331_2022, clausula_setima_pagamento, direito_bndes_deduzir, 'pagamentos efetuados a maior ou em duplicidade', 'Parágrafo Décimo Quinto').
contract_clause(contrato_ocs_331_2022, clausula_oitava_equilibrio_economico_financeiro_contrato, 'CLÁUSULA OITAVA- EQUILÍBRIO ECONÔMICO-FINANCEIRO DO CONTRATO \nO BNDES e o CONTRATADO têm direito ao equilíbrio econômico-financeiro do Contrato, em \nconsonância com o inciso XXI , do artigo 37, da Constituição Federal, a ser realizado mediante \nreajuste ou revisão de preços.', ' ').
contract_clause_fact(contrato_ocs_331_2022, clausula_oitava_equilibrio_economico_financeiro_contrato, direito_equilibrio, ['equilíbrio econômico-financeiro do Contrato', 'reajuste', 'revisão de preços'], 'trecho_literal').
contract_clause(contrato_ocs_331_2022, clausula_oitava_paragrafo_primeiro, 'Parágrafo Primeiro \nO  reajuste  de  preços,  na  forma  prevista  na  legislação,  poderá  ser  requerido  pelo \nCONTRATADO  a  cada  período  de  12  {doze)  meses,  sendo  o  primeiro  contado  do  dia \n03/11/2022,  data  da  sessão  pública  inaugural,  e  os  seguintes,  do  fato  gerador  anterior, \nadotando-se para tanto a aplicação do índice de Custo da Tecnologia da Informação - ICTI, \ndivulgado pelo Instituto de Pesquisa Econômica e Aplicada- lPEA, sobre o preço referido na \nCláusula de Preço deste Instrumento.', ' ').
contract_clause_fact(contrato_ocs_331_2022, clausula_oitava_paragrafo_primeiro, periodicidade_reajuste, 'a cada período de 12 meses', 'trecho_literal').
contract_clause_fact(contrato_ocs_331_2022, clausula_oitava_paragrafo_primeiro, data_inicial_reajuste, '03/11/2022', 'trecho_literal').
contract_clause_fact(contrato_ocs_331_2022, clausula_oitava_paragrafo_primeiro, indice_reajuste, 'Índice de Custo da Tecnologia da Informação - ICTI', 'trecho_literal').
contract_clause(contrato_ocs_331_2022, clausula_oitava_paragrafo_segundo, 'Parágrafo Segundo \nA revisão de preços poderá ser realizada por iniciativa do BNDES ou mediante solicitação do \nCONTRATADO,  quando ocorrer  fato  imprevisível ou  previsível,  porém, de consequências \nincalculáveis, retardador ou impeditivo da execução do Contrato, ou ainda em  caso de força \nmaior,  caso  fortuito  ou  fato  do  príncipe,  configurando  álea  econômica  extraordinária  e \nextracontratual, que onere ou desonere as obrigações pactuadas no presente  Instrumento, \nsendo,  porém, vedada nas  hipóteses em  que o  risco seja alocado ao CONTRATADO  nos \ntermos da Cláusula de Matriz de Riscos,  respeitando-se o seguinte:', ' ').
contract_clause_fact(contrato_ocs_331_2022, clausula_oitava_paragrafo_segundo, motivos_revisao, ['fato  imprevisível', 'fato  previsível', 'consequências incalculáveis', 'força maior', 'caso  fortuito', 'fato  do  príncipe'], 'trecho_literal').
contract_clause(contrato_ocs_331_2022, clausula_oitava_paragrafo_segundo_i, '1.  o  CONTRATADO deverá formular  ao BNDES requerimento  para a  revisão  do Contrato, \ncomprovando a ocorrência do fato gerador;', ' ').
contract_clause(contrato_ocs_331_2022, clausula_oitava_paragrafo_segundo_ii, 'li. a comprovação será realizada por meio de documentos, tais  como,  atos  normativos que \ncriem ou alterem tributos, lista de preço de fabricantes, notas fiscais de aquisição de matérias \nprimas, de transporte  de mercadorias, alusivas  à época da elaboração da proposta ou  do \núltimo reajuste e do momento do pedido de revisão; e', ' ').
contract_clause_fact(contrato_ocs_331_2022, clausula_oitava_paragrafo_segundo_ii, documentos_revisao, ['atos  normativos', 'lista de preço de fabricantes', 'notas fiscais de aquisição de matérias primas', 'transporte  de mercadorias'], 'trecho_literal').
contract_clause(contrato_ocs_331_2022, clausula_oitava_paragrafo_segundo_iii, 'Ili. com o requerimento,  o CONTRATADO deverá apresentar planilhas de custos unitários, \ncomparativas entre a data da formulação da proposta ou do último reajuste e o momento do\n\n6 \n\n\n~ BNDES  Classlllcação: DQCumemo Osrensivo (Lei n• 13.303/2016) \n\n■.À \n\nUnidade Gestora: AJ1/JUUCIGLIC4 \n\npedido de revisão, contemplando os custos unitários envolvidos e evidenciando o quanto o \naumento de preços ocorrido repercute no valor pactuado.', ' ').
contract_clause_fact(contrato_ocs_331_2022, clausula_oitava_paragrafo_segundo_iii, documentos_revisao, 'planilhas de custos unitários', 'trecho_literal').
contract_clause(contrato_ocs_331_2022, clausula_oitava_paragrafo_terceiro, 'Parágrafo Terceiro \nIndependentemente  de  solicitação,  o  BNDES  poderá  convocar  o  CONTRATADO  para \nnegociar a redução dos preços, mantendo o mesmo objeto contratado, na quantidade e nas \nespecificações indicadas na proposta, em virtude da redução dos preços de mercado, ou de \nitens  que  compõem  o  custo,  cabendo  ao  CONTRATADO  apresentar  as  informações \nsolicitadas pelo BNDES.', ' ').
contract_clause(contrato_ocs_331_2022, clausula_oitava_paragrafo_quarto, 'Parágrafo Quarto \nO CONTRATADO deverá solicitar o reajuste e/ou  a revisão de preços até a prorrogação ou \no  encerramento  do Contrato,  hipótese em  que os  efeitos financeiros  serão  concedidos  de \nmodo retroativo a partir do fato gerador, observando-se, ainda, que:', ' ').
contract_clause_fact(contrato_ocs_331_2022, clausula_oitava_paragrafo_quarto, prazo_solicitacao_reajuste_revisao, 'até a prorrogação ou o  encerramento  do Contrato', 'trecho_literal').
contract_clause(contrato_ocs_331_2022, clausula_oitava_paragrafo_quarto_i, '1.  caso  o fato gerador do  reajuste  e/ou  da revisão de preços ou  a divulgação do  índice  de \nreajuste  ocorra  com  antecedência  inferior  a  60  (sessenta)  dias  da  prorrogação  ou  do \nencerramento do Contrato, o CONTRATADO terá o prazo de 60 (sessenta) dias, a contar do \nfato gerador ou  da data de divulgação do índice, para solicitar o reaj uste e/ou  a revisão  de \npreços;', ' ').
contract_clause_fact(contrato_ocs_331_2022, clausula_oitava_paragrafo_quarto_i, prazo_solicitacao_reajuste_revisao, '60 dias', 'trecho_literal').
contract_clause(contrato_ocs_331_2022, clausula_oitava_paragrafo_quarto_ii, 'li.  caso  a  assinatura  do  aditivo  de  prorrogação  torne  superveniente  a  ocorrência  do  fato \ngerador do reajuste, ou a divulgação do índice de reajuste  ocorra após a prorrogação ou o \nencerramento do Contrato, o CONTRATADO terá o prazo de 60 (sessenta) dias, a contar do \nfato gerador ou da data de divulgação do índice, para solicitar o reajuste de preços;', ' ').
contract_clause_fact(contrato_ocs_331_2022, clausula_oitava_paragrafo_quarto_ii, prazo_solicitacao_reajuste_revisao, '60 dias', 'trecho_literal').
contract_clause(contrato_ocs_331_2022, clausula_oitava_paragrafo_quarto_iii, 'Ili.  o  BNDES  deverá  analisar  o  pedido  de  reajuste  e/ou  revisão  de  preços  em  até  60 \n(sessenta) dias, contados da solicitação e da entrega pelo CONTRATADO dos comprovantes \nde  variação  dos  custos,  ficando  este  prazo  suspenso,  a  critério  do  BNDES,  enquanto  o \nCONTRATADO não apresentar a documentação solicitada para a comprovação da variação \nde custos; e', ' ').
contract_clause_fact(contrato_ocs_331_2022, clausula_oitava_paragrafo_quarto_iii, prazo_analise_bndes, '60 dias', 'trecho_literal').
contract_clause(contrato_ocs_331_2022, clausula_oitava_paragrafo_quarto_iv, 'IV. caso o CONTRATADO não solicite o reajuste e/ou revisão de preços nos prazos fixados \nacima, não fará jus aos efeitos retroativos ou, caso o Contrato esteja encerrado, operar-se-á \na renúncia a eventual direito ao reajuste e/ou à revisão.', ' ').
contract_clause_fact(contrato_ocs_331_2022, clausula_oitava_paragrafo_quarto_iv, consequencia_nao_solicitacao, 'não fará jus aos efeitos retroativos', 'trecho_literal').
contract_clause(contrato_ocs_331_2022, clausula_oitava_paragrafo_quinto, 'Parágrafo Quinto \nSe  o  processo de  reajuste  e/ou  revisão  de preços  não for concluído  até o  vencimento  do \nContrato, e este  for prorrogado, sua continuidade após o  reequilíbrio  econômico-financeiro \nficará  condicionada à  manutenção da proposta do  CONTRATADO como  a condição  mais \nvantajosa para o BNDES, podendo este:', ' ').
contract_clause_fact(contrato_ocs_331_2022, clausula_oitava_paragrafo_quinto, condicao_prorrogacao_nao_concluida, 'manutenção da proposta do  CONTRATADO como  a condição  mais vantajosa para o BNDES', 'trecho_literal').
contract_clause(contrato_ocs_331_2022, clausula_oitava_paragrafo_quinto_i, '1. realizar negociação de preços junto ao CONTRATADO, de forma a viabilizar a continuidade \ndo  ajuste,  quando  os  novos  valores  fixados  após  o  reajuste  e/ou  a  revisão  de  preços \nestiverem acima do patamar apurado no mercado; ou', ' ').
contract_clause(contrato_ocs_331_2022, clausula_oitava_paragrafo_quinto_ii, 'li. rescindir o Contrato,  mediante aviso prévio ao  CONTRATADO, com  antecedência de 30 \n(trinta) dias, quando resultar infrutífera a negociação indicada no inciso anterior.', ' ').
contract_clause_fact(contrato_ocs_331_2022, clausula_oitava_paragrafo_quinto_ii, prazo_suspensao, '30 dias', 'trecho_literal').
contract_clause_fact(contrato_ocs_331_2022, clausula_oitava_paragrafo_quinto_ii, formas_rescisao, 'rescindir o Contrato', 'trecho_literal').
contract_clause(contrato_ocs_331_2022, clausula_oitava_paragrafo_sexto, 'Parágrafo Sexto \nNa ocorrência da hipótese prevista no  inciso li do Parágrafo anterior, o CONTRATADO fará \njus à integralidade dos valores apurados no processo de reajuste e/ou revisão de preços até \no  término do Contrato,  não  podendo, todavia,  reclamar qualquer indenização  em  razão  da \nrescisão do mesmo.', ' ').
contract_clause(contrato_ocs_331_2022, clausula_nona_matriz_riscos, 'CLÁUSULA NONA - MATRIZ DE RISCOS \nO BNDES e o CONTRATADO, tendo como premissa a obtenção do melhor custo contratual \nmediante  a  alocação  do  risco  à  parte  com  maior  capacidade  para  geri-lo  e  absorvê-lo, \nidentificam os  riscos decorrentes da relação contratual e, sem  prejuízo de outras previsões \ncontratuais,  estabelecem  os  respectivos  responsáveis  na  Matriz  de  Riscos  constante  do \nAnexo 111  deste Contrato.', ' ').
contract_clause_fact(contrato_ocs_331_2022, clausula_nona_matriz_riscos, anexo_matriz_riscos, 'Anexo 111', 'trecho_literal').
contract_clause(contrato_ocs_331_2022, clausula_nona_paragrafo_primeiro, 'Parágrafo Primeiro \nO  reajuste  de preço aludido na Matriz  de Riscos deve  respeitar o disposto  na\n\nCláusula de \nEquilíbrio Econômico-Financeiro deste Contrato.', ' ').
contract_clause_fact(contrato_ocs_331_2022, clausula_nona_paragrafo_primeiro, reajuste_matriz, 'respeitar o disposto  na Cláusula de Equilíbrio Econômico-Financeiro', 'trecho_literal').
contract_clause(contrato_ocs_331_2022, clausula_nona_paragrafo_segundo, 'Parágrafo Segundo \nÉ  vedada  a  celebração  de  aditivos  decorrentes  de  eventos  supervenientes  alocados,  na \nMatriz de Riscos, como de responsabilidade do CONTRATADO.', ' ').
contract_clause_fact(contrato_ocs_331_2022, clausula_nona_paragrafo_segundo, vedacao_aditivos, 'eventos  supervenientes  alocados,  na Matriz de Riscos, como de responsabilidade do CONTRATADO', 'trecho_literal').
contract_clause(contrato_ocs_331_2022, clausula_decima_garantia_contratual, 'CLÁUSULA DÉCIMA - GARANTIA CONTRATUAL \nO CONTRATADO prestará, no prazo de até 15 (quinze) dias úteis, contados da convocação, \ngarantia  contratual,  sob  pena  de  aplicação  de  penalidade  nos  termos  deste  Contrato, \nobservadas as condições para sua aceitação estipuladas nos incisos abaixo, no valor de R$ \n33.499,98  (trinta e três mil, quatrocentos e noventa e nove reais e noventa e oito centavos), \nque lhe será devolvida após a verificação do cumprimento fiel, correto e integral dos termos \ncontratuais.', ' ').
contract_clause_fact(contrato_ocs_331_2022, clausula_decima_garantia_contratual, valor_garantia, '33.499,98', 'trecho_literal').
contract_clause_fact(contrato_ocs_331_2022, clausula_decima_garantia_contratual, prazo_apresentacao_documento, '15 dias úteis', 'trecho_literal').
contract_clause(contrato_ocs_331_2022, clausula_decima_caucao_dinheiro, '1.  Caução  em  dinheiro:  deverá  ser  depositada  em  favor  do  BNDES,  de  acordo  com  as \norientações que serão fornecidas quando da referida convocação;', ' ').
contract_clause_fact(contrato_ocs_331_2022, clausula_decima_caucao_dinheiro, tipo_garantia, 'Caução  em  dinheiro', 'trecho_literal').
contract_clause(contrato_ocs_331_2022, clausula_decima_seguro_garantia, 'li. Seguro Garantia: a  Apólice de Seguro deverá ser emitida por Instituição autorizada pela \nSUSEP a operar no mercado securitário, que não se encontre sob regime de Direção Fiscal, \nIntervenção, Liquidação  Extrajudicial ou  Fiscalização  Especial, e que não esteja cumprindo \npenalidade de suspensão imposta pela SUSEP;', ' ').
contract_clause_fact(contrato_ocs_331_2022, clausula_decima_seguro_garantia, tipo_garantia, 'Seguro Garantia', 'trecho_literal').
contract_clause(contrato_ocs_331_2022, clausula_decima_seguro_garantia_a, 'a) O Instrumento de Apólice de Seguro deve prever expressamente:', ' ').
contract_clause(contrato_ocs_331_2022, clausula_decima_seguro_garantia_a_1, 'a.1)  responsabilidade  da seguradora  por todas  e  quaisquer  multas  de  caráter \nsancionatório aplicadas ao CONTRATADO;', ' ').
contract_clause_fact(contrato_ocs_331_2022, clausula_decima_seguro_garantia_a_1, responsabilidade_contratado, 'responsabilidade  da seguradora  por todas  e  quaisquer  multas  de  caráter sancionatório aplicadas ao CONTRATADO', 'trecho_literal').
contract_clause(contrato_ocs_331_2022, clausula_decima_seguro_garantia_a_2, 'a.2) vigência pelo prazo contratual;', ' ').
contract_clause_fact(contrato_ocs_331_2022, clausula_decima_seguro_garantia_a_2, prazo_vigencia, 'vigência pelo prazo contratual', 'trecho_literal').
contract_clause(contrato_ocs_331_2022, clausula_decima_seguro_garantia_a_3, 'a.3)  prazo  de  90  (noventa)  dias,  contados  a  partir  do  término  da  vigência \ncontratual,  para  apuração  de  eventual  inadimplemento  do  CONTRATADO  - ocorrido durante a vigência contratual -, e para a comunicação da expectativa de \nsinistro  ou  do  efetivo  aviso  de  sinistro,  observados  os  prazos  prescricionais \npertinentes.', ' ').
contract_clause_fact(contrato_ocs_331_2022, clausula_decima_seguro_garantia_a_3, prazo_validade_garantia, '90 dias', 'trecho_literal').
contract_clause(contrato_ocs_331_2022, clausula_decima_fianca_bancaria, 'Ili.  Fiança  Bancária:  a  Carta  de  Fiança  deverá  ser  emitida  por  Instituição  Financeira \nautorizada  pelo  Banco  Central  do  Brasil  - BACEN  para funcionar  no  Brasil  e  que não  se \nencontre em processo de liquidação extrajudicial ou de intervenção do BACEN.', ' ').
contract_clause_fact(contrato_ocs_331_2022, clausula_decima_fianca_bancaria, tipo_garantia, 'Fiança  Bancária', 'trecho_literal').
contract_clause(contrato_ocs_331_2022, clausula_decima_fianca_bancaria_a, 'a) O Instrumento de Fiança deve prever expressamente:', ' ').
contract_clause(contrato_ocs_331_2022, clausula_decima_fianca_bancaria_a_1, 'a.1) renúncia expressa, pelo fiador, ao benefício de ordem disposto no artigo 827 \ndo Código Civil;', ' ').
contract_clause(contrato_ocs_331_2022, clausula_decima_fianca_bancaria_a_2, 'a.2) vigência pelo prazo contratual;', ' ').
contract_clause_fact(contrato_ocs_331_2022, clausula_decima_fianca_bancaria_a_2, prazo_vigencia, 'vigência pelo prazo contratual', 'trecho_literal').
contract_clause(contrato_ocs_331_2022, clausula_decima_fianca_bancaria_a_3, 'a.3)  prazo  de  90  (noventa)  dias,  contados  a  partir  do  término  da  vigência \ncontratual,  para  apuração  de  eventual  inadimplemento  do  CONTRATADO  - ocorrido durante a vigência contratual -, e para a comunicação do inadimplemento \nà Instituição Financeira, observados os prazos prescricionais pertinentes.', ' ').
contract_clause_fact(contrato_ocs_331_2022, clausula_decima_fianca_bancaria_a_3, prazo_validade_garantia, '90 dias', 'trecho_literal').
contract_clause(contrato_ocs_331_2022, clausula_decima_paragrafo_primeiro, 'Parágrafo Primeiro \nO prazo previsto para a apresentação da garantia poderá ser prorrogado, por igual período, \nquando solicitado pelo CONTRATADO durante o respectivo transcurso, e desde que ocorra \nmotivo justificado e aceito pelo BNDES.', ' ').
contract_clause(contrato_ocs_331_2022, clausula_decima_paragrafo_segundo, 'Parágrafo Segundo \nHavendo majoração do preço contratado, decorrente de reajuste, repactuação ou revisão de \npreços  causada  por  alterações  na  legislação  tributária,  fica  dispensada  a  atualização  da \ngarantia, salvo se  o  valor da  atualização for igual  ou  superior ao  patamar referenciado  no \ninciso li do artigo 91  do Regulamento de Licitações e Contratos do SISTEMA BNDES.', ' ').
contract_clause(contrato_ocs_331_2022, clausula_decima_paragrafo_terceiro, 'Parágrafo Terceiro \nNos demais casos que demandem a complementação ou  renovação da garantia, tais como \nalteração do objeto (aditivo quantitativo ou qualitativo), prorrogação contratual, dentre outros, \no CONTRATADO deverá providenciá-la no prazo estipulado pelo BNDES.', ' ').
contract_clause(contrato_ocs_331_2022, clausula_decima_paragrafo_quarto, 'Parágrafo Quarto \nSempre  que  o  contrato  for  garantido  por  fiança  bancária  ou  seguro  garantia,  o \nCONTRATADO deve obter do garantidor anuência em relação à manutenção da garantia, no \nprazo de 1 O (dez)  dias  úteis  a contar da assinatura do  aditivo ou recebimento  de carta de \napostilamento ou  aditivo epistolar, conforme o caso.  Recusando-se o garantidor a manter a \ngarantia, cabe ao CONTRATADO obter nova garantia no mesmo prazo, prorrogável por igual \nperíodo a critério do BNDES.', ' ').
contract_clause_fact(contrato_ocs_331_2022, clausula_decima_paragrafo_quarto, prazo_apresentacao_documento, '1 O dias úteis', 'trecho_literal').
contract_clause(contrato_ocs_331_2022, clausula_decima_primeira_obrigacoes_contratado, 'CLÁUSULA DÉCIMA PRIMEIRA-OBRIGAÇÕES DO CONTRATADO 
Além  de  outras  obrigações  estabelecidas  neste  Instrumento,  em  seus  anexos ou  nas  leis 
vigentes,  particularmente  na  Lei  nº  13.303/2016,  ou  que  entrarem  em  vigor,  constituem 
obrigações do CONTRATADO: 

1.  manter durante a vigência deste Contrato todas as condições de habilitação e a ausência 
de impedimentos exigidas  quando da contratação,  comprovando-as  sempre que solicitado 
pelo BNDES; 

9 





li.  comunicar a  imposição  de  penalidade  que  acarrete  o  impedimento  de  contratar  com  o 
BNDES, bem como a eventual perda dos pressupostos para a licitação; 

Ili. reparar, corrigir, remover, reconstruir ou substituir, às suas expensas, no total ou em parte, 
o  objeto do Contrato  em  que se verificarem  vícios, defeitos ou  incorreções  decorrentes da 
execução; 

IV.  reparar todos  os danos  e  prejuízos  causados  ao  BNDES  ou  a  terceiros,  não  restando 
excluída  ou  reduzida  esta  responsabilidade  pela  presença  de  fiscalização  ou  pelo 
acompanhamento da execução por parte do Gestor do Contrato; 

V.  pagar  todos  os  encargos  e  tributos,  que  incidam  ou  venham  a  incidir,  direta  ou 
indiretamente, sobre o objeto deste Contrato, podendo o BNDES, a qualquer momento, exigir 
do CONTRATADO a comprovação de sua regularidade; 

VI.  assumir a  responsabilidade integral  por quaisquer ônus que venham a  ser  impostos ao 
BNDES  em virtude de documento  fiscal que seja  emitido em  desacordo com  a  legislação 
aplicável; 

VII. providenciar, perante a  Receita Federal do Brasil - RFB, comprovando ao BNDES, sua 
exclusão  obrigatória  do  Simples  Nacional,  no  prazo  estipulado  pelo  artigo  30  da  Lei 
Complementar nº 123/2006, se o CONTRATADO, quando optante : 

a)  extrapolar o limite de receita bruta anual previsto no artigo 3º da Lei Complementar 
nº 123/2006, ao longo da vigência deste Contrato; ou 

b) enquadrar-se em alguma das situações previstas no artigo 17 da Lei Complementar 
nº 123/2006; 

VIII. permitir vistorias e acompanhamento da execução do objeto pelo Gestor do Contrato; 

IX.  obedecer  às  instruções  e  aos  procedimentos,  estabelecidos  pelo  BNDES,  para  a 
adequada execução do Contrato; 

X. designar 01  (um) preposto como responsável pelo Contrato firmado com o  BNDES, para 
participar  de  eventuais  reuniões  e  ser  o  interlocutor  do CONTRATADO,  zelando  pelo  fiel 
cumprimento das obrigações previstas neste Instrumento; 

XI. apresentar, em até 1 O (dez) dias úteis após a convocação, a Declaração de Informações 
para  Fornecimento  - DIF,  adequadamente  preenchida,  sob  pena  de  instauração  de 
procedimento punitivo para aplicação de penalidade, e de retenção tributária, pelo  BNDES, 
nos casos previstos em lei, da alíquota que entender adequada; 

a)  as  informações inseridas  na Declaração de  Informações para Fornecimento - DIF 
não deverão divergir das constantes do documento fiscal ou equivalente legal; 

XII.  devolver  recursos  disponibilizados  pelo  BNDES,  revogar  perfis  de  acesso  de  seus 
profissionais, eliminar suas caixas postais e adotar demais providências aplicáveis ao término 
da vigência deste Contrato;', 'trecho_literal').
contract_clause_fact(contrato_ocs_331_2022, clausula_decima_primeira_obrigacoes_contratado, obrigacoes, ['manter durante a vigência deste Contrato todas as condições de habilitação e a ausência de impedimentos exigidas quando da contratação', 'comunicar a imposição de penalidade que acarrete o impedimento de contratar com o BNDES', 'reparar, corrigir, remover, reconstruir ou substituir, às suas expensas, o objeto do Contrato em que se verificarem vícios, defeitos ou incorreções decorrentes da execução', 'reparar todos os danos e prejuízos causados ao BNDES ou a terceiros', 'pagar todos os encargos e tributos', 'assumir a responsabilidade integral por quaisquer ônus que venham a ser impostos ao BNDES em virtude de documento fiscal que seja emitido em desacordo com a legislação aplicável', 'providenciar, perante a Receita Federal do Brasil - RFB, comprovando ao BNDES, sua exclusão obrigatória do Simples Nacional', 'permitir vistorias e acompanhamento da execução do objeto pelo Gestor do Contrato', 'obedecer às instruções e aos procedimentos, estabelecidos pelo BNDES, para a adequada execução do Contrato', 'designar 01 (um) preposto como responsável pelo Contrato firmado com o BNDES', 'apresentar, em até 1 O (dez) dias úteis após a convocação, a Declaração de Informações para Fornecimento - DIF', 'devolver recursos disponibilizados pelo BNDES, revogar perfis de acesso de seus profissionais, eliminar suas caixas postais e adotar demais providências aplicáveis ao término da vigência deste Contrato'], 'trecho_literal').
contract_clause(contrato_ocs_331_2022, clausula_decima_segunda_conduta_etica, 'CLÁUSULA DÉCIMA SEGUNDA- CONDUTA ÉTICA DO CONTRATADO E DO BNDES 
O CONTRATADO e o BNDES comprometem-se a manter a integridade nas relações público 
privadas, agindo de boa-fé e de acordo com os princípios da moralidade administrativa e da 

10 





impessoalidade,  além  de  pautar sua conduta por preceitos  éticos  e,  em  especial,  por  sua 
responsabilidade socioambiental. 

Em atendimento ao disposto no caputdesta Cláusula, o CONTRATADO obriga-se, inclusive, 
a: 

1.  não oferecer, prometer, dar, autorizar, solicitar ou aceitar, direta ou indiretamente, qualquer 
vantagem  indevida,  seja  pecuniária  ou  de  outra  natureza,  consistente  em  fraude,  ato  de 
corrupção  ou  qualquer outra violação de dever  legal,  relacionada com  este  Contrato, bem 
como a tomar todas as medidas ao seu alcance para impedir administradores, empregados, 
agentes,  representantes,  fornecedores,  contratados  ou  subcontratados,  seus  ou  de  suas 
controladas, de fazê-lo; 

li. impedir o favorecimento ou a participação de empregado ou dirigente do Sistema BNDES 
(BNDES e suas subsidiárias) na execução do objeto do presente Contrato; 

Ili.  providenciar  para  que  não  sejam  alocados,  na  execução  dos  serviços,  familiares  de 
dirigente  ou  empregado  do  Sistema  BNDES,  considerando-se  familiar  o  cônjuge,  o 
companheiro  ou o parente em linha reta ou colateral, por consanguinidade ou  afinidade, até 
o terceiro grau; 

IV.  observar a  Política para Transações  com  Partes  Relacionadas  e  o  Código de  Ética do 
Sistema  BNDES  vigentes  ao  tempo  da  contratação,  bem  como  a  Política  Corporativa 
Anticorrupção  do  Sistema  BNDES,  assegurando-se  de  que  seus 
representantes, 
administradores  e  todos  os  profissionais  envolvidos  na  execução  do  objeto  pautem  seu 
comportamento e sua atuação pelos princípios neles constantes; e 

V.  adotar,  na  execução  dos  serviços,  boas  práticas  de  sustentabilidade  ambiental,  de 
otimização de recursos, de redução de desperdícios e de redução da poluição. 

O  BNDES  recomenda1  ao  CONTRATADO,  considerar  em  suas  práticas  de  gestão  a 
implantação  de  programa  de  integridade  estruturado,  voltado  à  prevenção,  detecção  e 
remediação da ocorrência de fraudes e atos de corrupção. 

Verificada uma das situações mencionadas nos incisos  li  e  Ili do Parágrafo  Primeiro desta 
Cláusula, compete ao CONTRATADO afastar imediatamente da execução do Contrato os 
agentes que impliquem a ocorrência dos impedimentos e favorecimentos aludidos, além de 
comunicar tal fato ao BNDES, sem prejuízo de apuração de sua responsabilidade, caso tenha 
agido de má-fé. 

O  CONTRATADO declara ter conhecimento do Código de Ética do  Sistema  BNDES, bem 
como  da  Política  Corporativa  Anticorrupção  do  Sistema  BNDES,  que  poderão  ser 
consultados por intermédio do  sítio eletrônico  www.bndes.gov.br ou  requisitados ao Gestor 
do Contrato. 

11 





Eventuais  irregularidades  ou  descumprimentos  das  normas  internas  do  BNDES  ou  da 
legislação  vigente  podem  ser denunciados  à  Ouvidoria  por  qualquer cidadão  através  dos 
seguintes  canais:  página  na  internet  (www.bndes.qov.br/ouvidoria);  correio  (Caixa  Postal 
15054, CEP 20031 -120, Rio de Janeiro - RJ) ; e telefone (0800 702 6307).', 'trecho_literal').
contract_clause_fact(contrato_ocs_331_2022, clausula_decima_segunda_conduta_etica, obrigacoes, ['não oferecer, prometer, dar, autorizar, solicitar ou aceitar, direta ou indiretamente, qualquer vantagem indevida', 'impedir o favorecimento ou a participação de empregado ou dirigente do Sistema BNDES', 'providenciar para que não sejam alocados, na execução dos serviços, familiares de dirigente ou empregado do Sistema BNDES', 'observar a Política para Transações com Partes Relacionadas e o Código de Ética do Sistema BNDES', 'adotar, na execução dos serviços, boas práticas de sustentabilidade ambiental'], 'trecho_literal').
contract_clause(contrato_ocs_331_2022, clausula_decima_terceira_sigilo_informacoes, 'CLÁUSULA DÉCIMA TERCEIRA - SIGILO DAS INFORMAÇÕES 
Cabe  ao  CONTRATADO cumprir  as  seguintes  regras  de  sigilo  e  assegurar a aceitação  e 
adesão às  mesmas  por profissionais que  integrem  ou  venham  a integrar  a sua  equipe  na 
prestação  do  objeto  deste  Contrato,  as  quais  perdurarão,  inclusive,  após  a  cessação  do 
vínculo contratual e da prestação dos serviços: 

1.  cumprir as diretrizes  e  normas  da Política  Corporativa  de  Segurança da  Informação  do 
BNDES, necessárias para assegurar a íntegra e o sigilo das informações; 

li. não acessar informações sigilosas do  BNDES, salvo quando previamente autorizado por 
escrito; 

Ili. sempre que tiver acesso às informações mencionadas no inciso anterior: 

a)  manter sigilo dessas informações, não podendo copiá-las, reproduzi-las, retê-las ou 
praticar  qualquer outra forma  de  uso  que  não  seja  imprescindível  para a  adequada 
prestação do objeto deste Contrato; 

b)  limitar  o  acesso  às  informações  aos  profissionais  envolvidos  na  prestação  dos 
serviços objeto deste Contrato, os quais deverão estar cientes da natureza sigilosa das 
informações  e  das  obrigações  e  responsabilidades  decorrentes  do  uso  dessas 
informações; e 

e)  informar  imediatamente  ao  BNDES  qualquer  violação  das  regras  de  sigilo  ora 
estabelecidas  que tenha  ocorrido  por  sua  ação  ou  omissão,  independentemente  da 
existência  de  dolo,  bem  como  dos  profissionais  envolvidos,  adotando  todas  as 
orientações do BNDES para remediar a violação; 

IV.  entregar ao BNDES, ao término da vigência deste Contrato, todo e qualquer material de 
propriedade  deste,  inclusive  notas  pessoais  envolvendo  matéria  sigilosa  e  registro  de 
documentos  de  qualquer  natureza que tenham  sido  criados,  usados ou  mantidos  sob  seu 
controle ou posse,  assumindo o compromisso de não  utilizar qualquer informação sigilosa a 
que teve acesso no âmbito deste Contrato; 

V.  apresentar,  antes  do  início  da  prestação  dos  serviços,  Termos  de  Confidencialidade, 
conforme  minuta  constante  do  Anexo  V  (Minuta  de  Termo  de  Confidencialidade  para 
Profissionais)  deste  Contrato,  assinados  pelos  profissionais  que  acessarão  informações 
sigilosas,  devendo  referida  obrigação  ser  também  cumprida  por  ocasião  de  substit uição 
desses profissionais; e 

VI. observar o disposto no Termo de Confidencialidade assinado por seu Representante Legal 
constante  do  Anexo  IV  (Termo  de  Confidencialidade  para  Representante  Legal)  deste 
Contrato. 

12 




Unidade Gestora: AJ1/JUUCIGLIC4', 'trecho_literal').
contract_clause_fact(contrato_ocs_331_2022, clausula_decima_terceira_sigilo_informacoes, obrigacoes, ['cumprir as diretrizes e normas da Política Corporativa de Segurança da Informação do BNDES', 'não acessar informações sigilosas do BNDES, salvo quando previamente autorizado por escrito', 'manter sigilo dessas informações', 'limitar o acesso às informações', 'informar imediatamente ao BNDES qualquer violação das regras de sigilo', 'entregar ao BNDES, ao término da vigência deste Contrato, todo e qualquer material de propriedade deste', 'apresentar, antes do início da prestação dos serviços, Termos de Confidencialidade', 'observar o disposto no Termo de Confidencialidade assinado por seu Representante Legal'], 'trecho_literal').
contract_clause(contrato_ocs_331_2022, clausula_decima_quarta_acesso_e_protecao_de_dados_pessoais, 'CLÁUSULA DÉCIMA QUARTA- ACESSO E PROTEÇÃO DE DADOS PESSOAIS 
As partes assumem o compromisso de proteger os direitos fundamentais de liberdade e de 
privacidade, relativos ao tratamento de dados pessoais, nos meios físicos e digitais, devendo, 
para  tanto,  adotar  medidas  corretas  de  segurança  sob  o  aspecto  técnico,  jurídico  e 
administrativo, e observar que: 

!.Eventual  tratamento  de  dados  em  razão  do  presente  Contrato  deverá  ser  realizado 
conforme os parâmetros previstos na legislação, especialmente na Lei nº 13.709/2018- Lei 
Geral de Proteção de Dados - LGPD, dentro de propósitos legítimos, específicos, explícitos 
e informados ao titular; 

li.O  tratamento  será  limitado  às  atividades  necessanas  ao  atingimento  das  finalidades 
contratuais  e,  caso  seja  necessário,  ao  cumprimento  de  suas  obrigações  legais  ou 
regulatórias,  sejam  de  ordem  principal  ou  acessória,  observando-se  que,  em  caso  de 
necessidade de coleta de dados pessoais, esta será realizada mediante prévia aprovação 
do BNDES, responsabilizando-se o CONTRATADO por obter o consentimento dos titulares, 
salvo nos casos em que a legislação dispense tal medida; 

Ili.O  CONTRATADO  deverá  seguir  as  instruções  recebidas  do  BNDES  em  relação  ao 

tratamento de dados pessoais; 

IV.O CONTRATADO se responsabilizará como "Controlador de dados" no caso do tratamento 
de dados para o cumprimento de suas obrigações legais ou regulatórias, devendo obedecer 
aos parâmetros previstos na legislação; 

V.Os  dados  coletados  somente  poderão  ser  utilizados  pelas  partes,  seus  representantes, 
empregados e prestadores de serviços diretamente alocados na execução contratual, sendo 
que, em hipótese alguma, poderão ser compartilhados ou utilizados para outros fins, sem a 
prévia  autorização  do  BNDES,  ou  caso  haja  alguma  ordem  judicial,  observando-se  as 
medidas legalmente previstas para tanto; 

VI.O CONTRATADO deve manter a confidencialidade dos dados pessoais obtidos em razão 
do presente contrato, devendo adotar as medidas técnicas e administrativas adequadas e 
necessárias, visando assegurar a proteção dos dados,  nos termos do artigo  46 da LGPD, 
de  modo  a  garantir  um  nível  apropriado  de  segurança  e  a  prevenção  e  mitigação  de 
eventuais riscos ; 

VII.Os dados deverão ser armazenados de maneira segura pelo CONTRATADO, que utilizará 
recursos  de  segurança  da  informação  e  tecnologia  adequados,  inclusive  quanto  a 
mecanismos de detecção e prevenção de ataques cibernéticos e incidentes de segurança 
da informação. 

VIII.O CONTRATADO dará conhecimento formal  para seus empregados e/ou  prestadores de 
serviço  acerca  das  disposições  previstas  nesta  Cláusula  e  na  Cláusula  de  Sigilo  das 
Informações,  responsabilizando-se  por  eventual  uso  indevido  dos  dados  pessoais,  bem 
como por quaisquer falhas nos sistemas por ela empregados para o tratamento dos dados. 

13 

IX.O  BNDES possui  direito de regresso  em face do CONTRATADO em  razão  de eventuais 
danos  causados  por  este  em  decorrência  do  descumprimento  das  responsabilidades  e 
obrigações  previstas  no  âmbito  deste  contrato  e  da  Lei  Geral  de  Proteção  de  Dados 
Pessoais; 

X.O CONTRATADO deverá disponibilizar ao titular do dado um canal ou sistema em que seja 
garantida  consulta  facilitada  e  gratuita  sobre  a  forma,  a  duração  do  tratamento  e  a 
integralidade de seus dados pessoais. 

XI.O  CONTRATADO  deverá  informar  imediatamente  ao  BNDES  todas  as  solicitações 
recebidas  em  razão  do exercício  dos  direitos  pelo  titular dos dados  relacionados  a  este 
Contrato,  seguindo as orientações fixadas pelo  BNDES e  pela  legislação em vigor para o 
adequado endereçamento das demandas. 

XII.O  CONTRATADO deverá manter registro  de todas as operações de tratamento de dados 
pessoais que realizar  no âmbito do Contrato  disponibilizando, sempre que  solicitado pelo 
BNDES,  as  informações  necessárias  à  produção  do  Relatório  de  Impacto  de  Dados 
Pessoais, disposto no artigo 5º,  XVII, da Lei Geral de Proteção de Dados Pessoais. 

XIII.Qualquer incidente que implique em violação ou risco de violação ou vazamento de dados 
pessoais deverá ser prontamente comunicado ao BNDES, informando-se também todas as 
providências  adotadas  e  os  dados  pessoais  eventualmente  afetados,  cabendo  ao 
CONTRATADO  disponibilizar  as  informações  e  documentos  solicitados  e  colaborar com 
qualquer investigação ou auditoria que venha a ser realizada. 

XIV.Ao  final  da  vigência  do  Contrato,  o  CONTRATADO  deverá  eliminar  de  sua  base  de 
informações todo e qualquer dado pessoal que tenha tido acesso em razão da execução do 
objeto contratado, salvo quando tenha que  manter a  informação  para o  cumprimento  de 
obrigação legal. 

As  Partes  reconhecem  que,  se durante a  execução  do  Contrato armazenarem, coletarem, 
tratarem  ou  de qualquer outra forma  processarem  dados  pessoais,  no  sentido  dado  pela 
legislação  vigente  aplicável,  o  BNDES  será  considerado  "Controlador  de  Dados",  e  o 
CONTRATADO "Operador" ou  "Processador de Dados",  salvo  nas situações expressas em 
contrário nesse Contrato. Contudo, caso o CONTRATADO descumpra as obrigações prevista 
na  legislação  de  proteção  de  dados  ou  as  instruções  do  BNDES,  será  equiparado  a 
"Controlador de Dados",  inclusive para fins  de sua  responsabilização  por eventuais  danos 
causados. 

Caso o CONTRATADO disponibilize dados de terceiros, além das obrigações no caput desta 
Cláusula,  deve  se  responsabilizar  por  eventuais  danos  que  o  BNDES  venha  a  sofrer  em 
decorrência de uso indevido de dados pessoais por parte do  CONTRATADO, sempre que 
ficar comprovado que houve falha de segurança técnica e administrativa, descumprimento de 
regras previstas na legislação de proteção à privacidade e dados pessoais, e das orientações 
do BNDES, sem prej uízo das penalidades deste contrato. 

14 

A  transferência  internacional  de  dados  deve  se  dar  em  caráter  excepcional  e  na  estrita 
observância da legislação, especialmente, dos artigos 33 a 36 da Lei nº 13.709/2018 e nos 
normativos  do  Banco  Central  do  Brasil  relativos  ao  processamento  e  armazenamento  de 
dados  das  instituições  financeiras,  e  dependerá  de  autorização  prévia  do  BNDES  ao 
CONTRATADO. 

A assinatura deste Contrato importa na manifestação de inequívoco consentimento do titular, 
seja  ele  pessoa  física  direta  ou  indiretamente  relacionada  ao  CONTRATADO,  inclusive 
sócios,  representantes  legais,  empregados,  contratados  e/ou  terceirizados,  quando  for  o 
caso, dos dados pessoais que tenham se tornados públicos como condição para participação 
na licitação e para contratação, para tratamento pelo BNDES, na forma da Lei nº 13. 709/2018. 
Poderão  ser  solicitados  pelo  BNDES  dados  pessoais  adicionais  a  fim  de  viabilizar  o 
cumprimento de obrigação legal. 

Os representantes legais signatários do presente autorizam a divulgação dos dados pessoais 
expressamente  contidos  nos  documentos  decorrentes  do  procedimento  de  licitação,  tais 
como  nome,  CPF,  e-mail,  telefone  e  cargo,  para  fins  de  publicidade  das  contratações 
administrativas no site institucional do BNDES e em cumprimento à Lei nº 12.527/ 2011  (Lei 
de Acesso à Informação). 

As partes comprometem-se a coletar o consentimento, quando necessário, conforme previsto 
na Lei  no  13.709/2018  (Lei  Geral  de  Proteção  de  Dados  - LGPD),  bem  como  informar os 
titulares  dos  dados  pessoais  mencionados  no  presente  instrumento,  para  as  finalidades 
descritas no parágrafo acima.', 'trecho_literal').
contract_clause_fact(contrato_ocs_331_2022, clausula_decima_quarta_acesso_e_protecao_de_dados_pessoais, obrigacoes, 'proteger os direitos fundamentais de liberdade e de privacidade', 'trecho_literal').
contract_clause_fact(contrato_ocs_331_2022, clausula_decima_quarta_acesso_e_protecao_de_dados_pessoais, legislacao_rescisao, 'Lei nº 13.709/2018- Lei Geral de Proteção de Dados - LGPD', 'trecho_literal').
contract_clause(contrato_ocs_331_2022, clausula_decima_quinta_obrigações_do_bndes, 'CLÁUSULA DÉCIMA QUINTA - OBRIGAÇÕES DO BNDES 
Além  de  outras  obrigações  estipuladas  neste  Instrumento,  em  seus  anexos  ou  nas  leis 
obrigações do BNDES: 

1.  realizar  os  pagamentos  devidos  ao  CONTRATADO,  nas  condições  estabelecidas  neste 

li. designar, como Gestor do Contrato, o Sr. Mario Roberto Ginglass, que atualmente exerce 
a  função  de  Gerente  na  AIC/DEROC/GSEG,  a  quem  caberá  o  acompanhamento,  a 
fiscalização e a avaliação da execução dos serviços, bem como a liquidação da despesa e o 
atestado de cumprimento das obrigações assumidas; 

Ili. designar, como substituto do Gestor do Contrato, para atuar em sua eventual ausência, o 
Sr. Giuliano  Freitas de Paula  Petrilo, que atualmente  exerce a  função  de Coordenador de 
Serviços na AIC/DEROC/GSEG; 

IV.  alterar,  quando  conveniente,  o  Gestor  do  Contrato  e/ou  o  seu  substituto,  por  outro 
profissional, mediante comunicação escrita ao CONTRATADO; 

15 

V.  designar  a  Comissão  de  Recebimento,  a  quem  caberá  o  recebimento  do  objeto,  em 
conjunto com o Gestor do Contrato; 

VI. fornecer ao CONTRATADO, quando solicitado ao Gestor do Contrato, acesso ao Código 
de Ética do Sistema BNDES, da Política Corporativa Anticorrupção do Sistema BNDES e da 
Política Corporativa de Segurança da Informação do BNDES; 

VII.  colocar  à  disposição  do CONTRATADO  todas  as informações  necessárias  à  perfeita 
execução dos serviços objeto deste Contrato; e 

VIII. comunicar ao CONTRATADO, por escrito: 

a) quaisquer instruções ou procedimentos sobre assuntos relacionados ao Contrato; 

b) a abertura de procedimento administrativo para a apuração de condutas irregulares 
do CONTRATADO, concedendo-lhe prazo para defesa; e 

e) a aplicação de eventual penalidade, nos termos deste Contrato.', 'trecho_literal').
